[[vk::binding(0, 0)]] RWTexture2D<float4> gOutput;
[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};
[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; };

[shader("raygeneration")]
void RayGen()
{
    uint2 idx = DispatchRaysIndex().xy;
    uint2 dim = DispatchRaysDimensions().xy;
    float2 uv = float2(idx) / float2(dim);
    float3 dir = normalize(float3(uv * 2.0 - 1.0, 1.0));

    RayDesc ray;
    ray.Origin = float3(0, 0, -2);
    ray.TMin = 0.001;
    ray.Direction = dir;
    ray.TMax = 100.0;

    Payload p;
    p.c = float4(0, 0, 0, 0);
    TraceRay(gScene, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);
    gOutput[idx] = p.c;
}

struct Payload { float4 c; };
[shader("miss")]
void Miss(inout Payload p)
{
    p.c = float4(0.1, 0.2, 0.8, 1.0);
}

struct Payload { float4 c; };
[shader("closesthit")]
void ClosestHit(inout Payload p, in BuiltInTriangleIntersectionAttributes a)
{
    p.c = float4(0.9, 0.3, 0.1, 1.0);
}
